examples.template:
VStack(alignment: .leading, spacing: 8) {
    HStack(spacing: 16) {
        Text({{items.0.label}}).monarchTextStyle(.body)
        Text({{items.0.value}}).monarchTextStyle(.body)
        MonarchProvenance({{items.0.source}}, checkedAt: Date.now.addingTimeInterval(-{{items.0.checkedHoursAgo|double}} * 3600), systemImage: "cylinder.split.1x2")
    }
    HStack(spacing: 16) {
        Text({{items.1.label}}).monarchTextStyle(.body)
        Text({{items.1.value}}).monarchTextStyle(.body)
        MonarchProvenance({{items.1.source}})
    }
}

